head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > emptyItem]<br/>inputType='select','autoComplete' 인 Column 에서 Cell 값이 목록에 없는 경우 처리 방식을 설정합니다.",
    "validation" : [
        "valueNotInList='keepValue' 인 경우 목록에 없는 Cell 값은 그대로 유지되며 emptyItem 속성은 Cell 값이 ''(Empty String)인 경우에만 적용됩니다.",
        "inputType='autoComplete' 이고 emptyItem=true 이면 noResult 속성은 항상 'clear' 로 동작합니다.",
        "단, chooseOption=true 이면 chooseOption 속성에 의해 표시되는 '-선택-' 항목이 선택됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "2" = true)
    con_emptyItem.setValue("2");
    con_valueNotInList.setValue("keepValue");
    con_noResult.setValue("useData");
    con_chooseOption.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - sel : inputType=select Column / ac : inputType=autoComplete Column (아이템 서울(S) / 부산(B) / 대구(D))
//  - Row 0 = 목록에 있는 값(S), Row 1 = 목록에 없는 값(J), Row 2 = ''(Empty String)
//  - con 속성은 sel / ac 두 Column 에 동일하게 적용 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단)
    let cEmptyItem = con_emptyItem.getText();
    let cValueNotInList = con_valueNotInList.getValue();
    let cNoResult = con_noResult.getValue();
    let cChooseOption = con_chooseOption.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Row 0 = 목록에 있는 값(S), Row 1 = 목록에 없는 값(J), Row 2 = 빈 값 / 아이템 : 서울(S), 부산(B), 대구(D)\n[절차] valueNotInList 확인 : Cell Value 확인 -> Row 1, Row 2 의 sel / ac 셀 더블클릭 -> 편집 모드 표시값 확인 -> Esc\nnoResult 확인 : Row 0 ac 셀 더블클릭 -> 입력값을 지우고 제주 입력 -> Enter -> Cell Value 확인\n[확인] Cell 에 저장된 Value 와 셀 표시값(괄호 안)"', '', 'label1');

    let attrCol = '';
    if (cEmptyItem !== '') {
        attrCol += ' emptyItem="' + cEmptyItem + '"';
    }
    if (cValueNotInList !== '') {
        attrCol += ' valueNotInList="' + cValueNotInList + '"';
    }
    if (cNoResult !== '') {
        attrCol += ' noResult="' + cNoResult + '"';
    }
    if (cChooseOption !== '') {
        attrCol += ' chooseOption="' + cChooseOption + '"';
    }

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ac" name="ac" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "sel" : "S", "ac" : "S" },
        { "name" : "김철수", "sel" : "J", "ac" : "J" },
        { "name" : "이영희", "sel" : "", "ac" : "" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column2" value="sel (select)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column3" value="ac (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="select" id="sel" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="autoComplete" id="ac" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 전체 Row 의 Cell Value(getCellData) 와 셀 표시값 출력
//  - validation 1 : Row 1(목록에 없는 값) 유지 여부, Row 2(빈 값) 처리
//  - validation 2, 3 : Row 0 ac 셀에 목록에 없는 값 입력 후 Value / 표시값 ('-선택-' 선택 여부)
scwin.btn_getCellValue_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let getText = function (rowIndex, colIndex) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_" + colIndex + "']");
        return td ? td.textContent : "";
    };
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        bottom.setReturnValue("Row " + i + " '" + target1.getCellData(i, "sel") + "' (" + getText(i, 1) + ") / '" + target1.getCellData(i, "ac") + "' (" + getText(i, 2) + ")");
    }
}
